-- Member 3 ownership: bookings and payments; property and user rows are prerequisites.
CREATE TABLE IF NOT EXISTS bookings (id VARCHAR(40) PRIMARY KEY,property_id VARCHAR(40) NOT NULL,buyer_id VARCHAR(40) NOT NULL,seller_id VARCHAR(40) NOT NULL,booking_date DATE NOT NULL,reservation_fee DECIMAL(15,2) NOT NULL,status ENUM('PENDING_APPROVAL','APPROVED','REJECTED','CONFIRMED','CANCELLED') NOT NULL,notes TEXT,payment_status VARCHAR(30) NOT NULL DEFAULT 'UNPAID',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(property_id) REFERENCES properties(id),FOREIGN KEY(buyer_id) REFERENCES users(id),FOREIGN KEY(seller_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments (id VARCHAR(40) PRIMARY KEY,booking_id VARCHAR(40) NOT NULL,buyer_id VARCHAR(40) NOT NULL,property_id VARCHAR(40) NOT NULL,amount DECIMAL(15,2) NOT NULL,payment_method ENUM('CREDIT_CARD','DEBIT_CARD','BANK_TRANSFER','DIGITAL_WALLET','CASH') NOT NULL,status ENUM('PENDING','PENDING_COLLECTION','COMPLETED','FAILED','REFUNDED') NOT NULL,transaction_reference VARCHAR(120) NOT NULL UNIQUE,payment_date DATETIME NOT NULL,notes TEXT,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(booking_id) REFERENCES bookings(id),FOREIGN KEY(buyer_id) REFERENCES users(id),FOREIGN KEY(property_id) REFERENCES properties(id)) ENGINE=InnoDB;
